def forward(self, x):
    x = self.proj(x)
    if self.flatten:
        x = x.flatten(2).transpose(1, 2)  # BCHW -> BNC
    x = self.norm(x)
    return x

torch.nn.modules.container.Sequential.source:
def forward(self, input):
    for module in self:
        input = module(input)
    return input

torch.nn.modules.normalization.LayerNorm.source:
def forward(self, input: Tensor) -> Tensor:
    return F.layer_norm(
        input, self.normalized_shape, self.weight, self.bias, self.eps)

